(1329556, 169396, 34556, '<td valign="top">Nice shot, the text detracts from the image.</td>', 'Nice shot, the text detracts from the image.', '2005-04-26 20:08:12.000000', NULL, 1),
(1329557, 170240, 6814, '<td valign="top">Because the lettering on the watch is out of focus, you''ve lost the ability to really "sell" with this image.  I like the attempt you''ve made, and your idea is sound, you just need to work a little on the execution.</td>', 'Because the lettering on the watch is out of focus, you''ve lost the ability to really "sell" with this image.  I like the attempt you''ve made, and your idea is sound, you just need to work a little on the execution.', '2005-04-26 20:08:55.000000', NULL, 1),
