(1334068, 169444, 4517, '<td valign="top">Lol, well funny. And the photo`s good to.8</td>', 'Lol, well funny. And the photo`s good to.8', '2005-04-27 16:46:54.000000', NULL, 1),
(1334071, 170355, 4517, '<td valign="top">Good colour, but not alot in focus.</td>', 'Good colour, but not alot in focus.', '2005-04-27 16:47:47.000000', NULL, 1),
(1334108, 169578, 32767, '<td valign="top">I''m not too sure about the lighting. On my screen this silver looks purple or pinkish.</td>', 'I''m not too sure about the lighting. On my screen this silver looks purple or pinkish.', '2005-04-27 16:57:48.000000', NULL, 1),
(1334121, 170325, 32767, '<td valign="top">It''s a neat concept but the piece seems as little lost in the flower. A different flower...perhaps darker or richer in color may have been a better choice</td>', 'It''s a neat concept but the piece seems as little lost in the flower. A different flower...perhaps darker or richer in color may have been a better choice', '2005-04-27 17:00:44.000000', NULL, 1),
(1334127, 170174, 32767, '<td valign="top">I don''t like the lighting to much and the rose seems to way dominate the image.</td>', 'I don''t like the lighting to much and the rose seems to way dominate the image.', '2005-04-27 17:02:20.000000', NULL, 1),
(1334355, 169286, 24976, '<td valign="top">the text make this too busy imo</td>', 'the text make this too busy imo', '2005-04-27 17:56:34.000000', NULL, 1),
(1334362, 170340, 24976, '<td valign="top">your text looks pixelated, you might want to try to look for the anti-aliasing feature in whatever program you used to add it.</td>', 'your text looks pixelated, you might want to try to look for the anti-aliasing feature in whatever program you used to add it.', '2005-04-27 17:58:10.000000', NULL, 1),
