(1334429, 169898, 24976, '<td valign="top">not a fan of the halo effect, love the blue gem though...</td>', 'not a fan of the halo effect, love the blue gem though...', '2005-04-27 18:11:25.000000', NULL, 1),
(1334434, 170046, 24976, '<td valign="top">closer up would have given it a more abstract feel with skin and jewelry which would have looked really cool imo. But nevertheless this is a well taken shot.</td>', 'closer up would have given it a more abstract feel with skin and jewelry which would have looked really cool imo. But nevertheless this is a well taken shot.', '2005-04-27 18:13:48.000000', NULL, 1),
(1334450, 170238, 24976, '<td valign="top">love the abstractionistic qualities here... wish you cropped the black a bit differently, right now it seems slightly off center but not enough off center to justify it being off center in the first place.</td>', 'love the abstractionistic qualities here... wish you cropped the black a bit differently, right now it seems slightly off center but not enough off center to justify it being off center in the first place.', '2005-04-27 18:16:58.000000', NULL, 1),
(1334459, 170074, 24976, '<td valign="top">imo poor use of text. (font,color and placement)</td>', 'imo poor use of text. (font,color and placement)', '2005-04-27 18:18:34.000000', NULL, 1),
(1334464, 170358, 24976, '<td valign="top">i really like your colors.</td>', 'i really like your colors.', '2005-04-27 18:19:07.000000', NULL, 1),
(1334526, 170358, 32221, '<td valign="top">A smaller aperature might have been good</td>', 'A smaller aperature might have been good', '2005-04-27 18:32:41.000000', NULL, 1),
(1334546, 170287, 32221, '<td valign="top">This looks very grainy and over procesed. Not sure grain would do well for an advertisement.</td>', 'This looks very grainy and over procesed. Not sure grain would do well for an advertisement.', '2005-04-27 18:38:31.000000', NULL, 1),
(1334590, 170357, 32221, '<td valign="top">I like this low-key style</td>', 'I like this low-key style', '2005-04-27 18:49:44.000000', NULL, 1),
(1334597, 170183, 32221, '<td valign="top">Nice watch, I like the second hand!</td>', 'Nice watch, I like the second hand!', '2005-04-27 18:52:07.000000', NULL, 1),
(1334600, 169861, 32221, '<td valign="top">good detail</td>', 'good detail', '2005-04-27 18:52:54.000000', NULL, 1),
(1334603, 170046, 19064, '<td valign="top">Outstanding</td>', 'Outstanding', '2005-04-27 18:53:24.000000', NULL, 1),
(1334613, 170094, 19064, '<td valign="top">Nice shot, not keen on the text, but still, the shot itself is worth a 7</td>', 'Nice shot, not keen on the text, but still, the shot itself is worth a 7', '2005-04-27 18:55:14.000000', NULL, 1),
(1334617, 169467, 32221, '<td valign="top">Nice focus on the ring, I might have preferred slightly deeper DOF so that the closer shells were more in focus</td>', 'Nice focus on the ring, I might have preferred slightly deeper DOF so that the closer shells were more in focus', '2005-04-27 18:55:48.000000', NULL, 1),
(1334619, 169821, 32221, '<td valign="top">Nice, looks like the sort of desplay you see in shop windows</td>', 'Nice, looks like the sort of desplay you see in shop windows', '2005-04-27 18:56:56.000000', NULL, 1),
