(1335268, 169578, 7466, '<td valign="top">Interesting piece and nice lighting.  The upper text might be a little overpowering, but overall a very good ad.</td>', 'Interesting piece and nice lighting.  The upper text might be a little overpowering, but overall a very good ad.', '2005-04-27 21:41:40.000000', NULL, 1),
(1335277, 170278, 7466, '<td valign="top">Very nice.  I love the composition and the sparkle on the jewels.</td>', 'Very nice.  I love the composition and the sparkle on the jewels.', '2005-04-27 21:47:54.000000', NULL, 1),
(1335278, 170224, 7466, '<td valign="top">Interesting composition.  There''s something distracting about the clasp though.</td>', 'Interesting composition.  There''s something distracting about the clasp though.', '2005-04-27 21:49:07.000000', NULL, 1),
(1335283, 170118, 7466, '<td valign="top">I like this.  The lighting is nice and the reflection interesting.  My only gripe would be the yellow line on the right...it''s distracting.</td>', 'I like this.  The lighting is nice and the reflection interesting.  My only gripe would be the yellow line on the right...it''s distracting.', '2005-04-27 21:50:50.000000', NULL, 1),
(1335284, 170165, 7466, '<td valign="top">Interesting presentation.  Nice lighting and great composition.</td>', 'Interesting presentation.  Nice lighting and great composition.', '2005-04-27 21:51:26.000000', NULL, 1),
(1335292, 169877, 7466, '<td valign="top">Interesting piece of jewelry.  A little sparkle on the diamonds would have improved the shot immensely.</td>', 'Interesting piece of jewelry.  A little sparkle on the diamonds would have improved the shot immensely.', '2005-04-27 21:54:25.000000', NULL, 1),
(1335295, 169010, 7466, '<td valign="top">Interesting approach.  A refreshing change from all the watch faces.</td>', 'Interesting approach.  A refreshing change from all the watch faces.', '2005-04-27 21:55:46.000000', NULL, 1),
(1335302, 169539, 7466, '<td valign="top">A little more gold, a little less prop and you''d have a gread ad.</td>', 'A little more gold, a little less prop and you''d have a gread ad.', '2005-04-27 21:57:09.000000', NULL, 1),
(1335311, 169741, 7466, '<td valign="top">Interesting composition and concept.</td>', 'Interesting composition and concept.', '2005-04-27 22:00:15.000000', NULL, 1),
(1335317, 170341, 7466, '<td valign="top">Interesting piece, but not much of an ad.</td>', 'Interesting piece, but not much of an ad.', '2005-04-27 22:03:38.000000', NULL, 1),
