(1346934, 167997, 30490, '<td valign="top">cute photo, but not something that would be used in a print ad for jewelry</td>', 'cute photo, but not something that would be used in a print ad for jewelry', '2005-04-30 15:50:41.000000', NULL, 1),
(1346936, 168569, 30490, '<td valign="top">Items are too close together to be effectively shown.</td>', 'Items are too close together to be effectively shown.', '2005-04-30 15:51:28.000000', NULL, 1),
(1346937, 170343, 30490, '<td valign="top">cute shot, but not really an ad for jewelry</td>', 'cute shot, but not really an ad for jewelry', '2005-04-30 15:51:55.000000', NULL, 1),
(1346940, 169433, 30490, '<td valign="top">not shiny and bright as it should be for a jewelry ad</td>', 'not shiny and bright as it should be for a jewelry ad', '2005-04-30 15:52:29.000000', NULL, 1),
(1346944, 169741, 30490, '<td valign="top">A good idea, if only you had been showcasing the watch or ring.  This could be an ad for "everyday" jewelry</td>', 'A good idea, if only you had been showcasing the watch or ring.  This could be an ad for "everyday" jewelry', '2005-04-30 15:53:34.000000', NULL, 1),
