(1348663, 170271, 6668, '<td valign="top">I like the composition and idea behind this ad, though to me the womens pose does not look natural, she looks a bit uneasy or nervous.</td>', 'I like the composition and idea behind this ad, though to me the womens pose does not look natural, she looks a bit uneasy or nervous.', '2005-05-01 01:56:47.000000', NULL, 1),
(1348665, 169256, 27894, '<td valign="top">Love the light refracting off, great job GL</td>', 'Love the light refracting off, great job GL', '2005-05-01 01:59:19.000000', NULL, 1),
