(1348668, 170309, 27894, '<td valign="top">Love the multi colors, the water droplets seem a little distracting overall great photo. GL</td>', 'Love the multi colors, the water droplets seem a little distracting overall great photo. GL', '2005-05-01 02:02:42.000000', NULL, 1),
(1348669, 170252, 27894, '<td valign="top">Great photo that contained "part" of a model subject. colors make it stand out nice and sharp. GL</td>', 'Great photo that contained "part" of a model subject. colors make it stand out nice and sharp. GL', '2005-05-01 02:04:15.000000', NULL, 1),
(1348670, 170359, 6668, '<td valign="top">beautiful bracelet/neclace though the focus seem a bit soft, also the red line is awfully distracting, really draws away from the charms in my opinion.</td>', 'beautiful bracelet/neclace though the focus seem a bit soft, also the red line is awfully distracting, really draws away from the charms in my opinion.', '2005-05-01 02:06:15.000000', NULL, 1),
(1348673, 170257, 27894, '<td valign="top">Nice angle, a little soft around the edges. Light refracting of the diamonds is great. GJ.</td>', 'Nice angle, a little soft around the edges. Light refracting of the diamonds is great. GJ.', '2005-05-01 02:07:07.000000', NULL, 1),
(1348678, 170327, 27894, '<td valign="top">Really looks like an advertisement, Reflection off the surface is a nice touch.  GL</td>', 'Really looks like an advertisement, Reflection off the surface is a nice touch.  GL', '2005-05-01 02:10:32.000000', NULL, 1),
(1348679, 169898, 27894, '<td valign="top">Good lighting, would have like to seen more detail on the band seems a bit to dark. good photo.</td>', 'Good lighting, would have like to seen more detail on the band seems a bit to dark. good photo.', '2005-05-01 02:11:44.000000', NULL, 1),
